create table if not exists users (id bigint generated by default as identity primary key,email text unique not null,password text not null,name text default '',role text not null check(role in ('student','teacher')),created_at timestamptz default now());
create table if not exists subjects (id bigint generated by default as identity primary key,owner_id bigint references users(id),name text not null,code text unique not null,created_at timestamptz default now());
create table if not exists enrollments (subject_id bigint references subjects(id),student_id bigint references users(id),joined_at timestamptz default now(),primary key(subject_id,student_id));
create table if not exists attendance (id bigint generated by default as identity primary key,subject_id bigint references subjects(id),student_id bigint references users(id),date date not null,present boolean default false,source text default 'face',unique(subject_id,student_id,date));
create index if not exists attendance_subject_date on attendance(subject_id,date);
create table if not exists photos (id bigint generated by default as identity primary key,student_id bigint references users(id) on delete cascade,path text,embedding jsonb,created_at timestamptz default now());
create table if not exists attendance_sessions (id bigint generated by default as identity primary key,subject_id bigint references subjects(id),taken_on date default current_date,source text not null);
alter table attendance add column if not exists session_id bigint references attendance_sessions(id);
alter table attendance add column if not exists overridden boolean default false;
insert into storage.buckets(id,name,public) values ('face-photos','face-photos',false) on conflict do nothing;
create policy "authenticated read face photos" on storage.objects for select to authenticated using (bucket_id='face-photos');
create policy "authenticated upload face photos" on storage.objects for insert to authenticated with check (bucket_id='face-photos');
